import{s as g}from"./supabase-Bz0haH2D.js";/* empty css             */const h=document.getElementById("registerForm"),d=document.getElementById("authError"),r=document.getElementById("registerBtn");function s(t){d.textContent=t,d.classList.add("show")}function f(){d.classList.remove("show")}h.addEventListener("submit",async t=>{var m,c,u;t.preventDefault(),f();const a=document.getElementById("regName").value.trim(),l=document.getElementById("regEmail").value.trim(),E=document.getElementById("regPhone").value.trim(),o=document.getElementById("regPassword").value;if(!a||a.length<2){s("कृपया योग्य नाव प्रविष्ट करा.");return}const i=E.replace(/\s|-/g,"");if(!/^[6-9]\d{9}$/.test(i)){s("कृपया योग्य १० अंकी मोबाईल नंबर प्रविष्ट करा.");return}if(o.length<6){s("पासवर्ड किमान ६ अक्षरे लांब असावा.");return}r.disabled=!0,r.textContent="⏳ खाते तयार होत आहे...";try{const{data:n,error:e}=await g.auth.signUp({email:l,password:o,options:{data:{full_name:a,phone:i}}});if(e)throw e;await g.auth.signInWithPassword({email:l,password:o}),window.location.href="/dashboard.html"}catch(n){let e="नोंदणी अयशस्वी. कृपया पुन्हा प्रयत्न करा.";(m=n.message)!=null&&m.includes("already registered")||(c=n.message)!=null&&c.includes("already been registered")?e="हा ईमेल आधीच नोंदणी झालेला आहे. कृपया लॉगिन करा.":(u=n.message)!=null&&u.includes("password")&&(e="पासवर्ड खूप कमकुवत आहे. कृपया मजबूत पासवर्ड वापरा."),s(e),r.disabled=!1,r.textContent="खाते तयार करा →"}});h.querySelectorAll("input").forEach(t=>{t.addEventListener("input",f)});
